# ── v8 · mass rank-1 rule + learned isomer reranker (romanrozen), guarded and checked ───────────────────────────────
import base64, zlib, hashlib, json, shutil, sys, time, traceback
_RR8_FEATURES = '"""Spectrum <-> candidate features for a learned same-formula isomer reranker (v8, romanrozen).\n\nBuilt on Spectral Parallax\'s MetFrag-lite enumeration (frag_rescore.py, imported as `frag`): every candidate gives the\nneutral masses of the pieces left after removing 0, 1 or 2 bonds of its heavy-atom graph. Each peak of each spectrum is\nmatched against `piece + dh*H + charge carrier` (dh -2..+3, the carriers its adduct allows) at two tolerances, and the\nfeatures describe how much of the spectrum the candidate explains, how cheaply (fewest cleavages), how precisely (mass\nerror), which peaks (top-k, high mass), plus agreement between neutral losses seen in the spectrum and the candidate\'s\nfunctional groups (sugars, acids, methoxy, ...). Features are averaged over the molecule\'s spectra, then the ranker sees\nthem both raw and centred within the candidate list (a list = the isomers being compared).\n\n    features_for_list(spectra, smiles_list, cache) -> np.ndarray [n_candidates, N_FEATURES] (NaN rows: unparsable)\n    FEATURE_NAMES\n"""\nfrom __future__ import annotations\n\nimport numpy as np\n\nimport frag_rescore as frag\n\nH = frag.H\nTOLS = (0.005, 0.012)\nH_SHIFTS = tuple(range(-2, 4))\nLOSSES = {                      # name: (neutral loss mass, SMARTS a candidate needs to lose it)\n    \'h2o\': (18.010565, \'[OX2H1]\'),\n    \'co2\': (43.989829, \'[CX3](=O)[OX2H1,OX1-]\'),\n    \'hcooh\': (46.005479, \'[CX3](=O)[OX2H1,OX1-]\'),\n    \'nh3\': (17.026549, \'[NX3;H2,H1;!$(NC=O)]\'),\n    \'ch3\': (15.023475, \'[CH3][OX2,NX3]\'),\n    \'ch3oh\': (32.026215, \'[CH3][OX2]\'),\n    \'c2h2o\': (42.010565, \'[CH3]C(=O)[O,N]\'),\n    \'hexose\': (162.052824, \'[OX2;R][CX4;R]1[OX2;R][CX4;R][CX4;R]([OX2])[CX4;R]([OX2])[CX4;R]1[OX2]\'),\n    \'dhex\': (146.057909, \'C[CX4;R]1[OX2;R][CX4;R]([OX2])[CX4;R]([OX2])[CX4;R]([OX2])[CX4;R]1[OX2]\'),\n    \'pentose\': (132.042259, \'[OX2][CX4;R]1[OX2;R][CX4;R][CX4;R]([OX2])[CX4;R]1[OX2]\'),\n    \'glcA\': (176.032088, \'OC(=O)[CX4;R]1[OX2;R][CX4;R]([OX2])[CX4;R]([OX2])[CX4;R]([OX2])[CX4;R]1[OX2]\'),\n    \'so3\': (79.956815, \'S(=O)(=O)[OX2H1,OX1-,OX2]\'),\n    \'co\': (27.994915, \'[CX3]=O\'),\n}\n_LOSS_PATTERNS = None\n\n\ndef _patterns():\n    global _LOSS_PATTERNS\n    if _LOSS_PATTERNS is None:\n        from rdkit import Chem\n        _LOSS_PATTERNS = {k: Chem.MolFromSmarts(v[1]) for k, v in LOSSES.items()}\n    return _LOSS_PATTERNS\n\n\nSPEC_FEATURES = [\'expl_k1_lin\', \'expl_k2_lin\', \'expl_k1_sqrt\', \'expl_k2_sqrt\', \'expl_k2_lin_tight\', \'expl_k2_sqrt_tight\',\n                 \'top5_k2\', \'top10_k2\', \'top10_k1\', \'top3_k1\', \'npeaks_k2\', \'hi_mass_k2\', \'lo_mass_k2\', \'h0_share\',\n                 \'mass_err_mda\', \'k2_only_share\']\nCAND_FEATURES = [\'log_n_k1\', \'log_n_k2\', \'heavy_atoms\', \'n_rings\', \'frac_aromatic\', \'n_O\', \'n_N\']\nLOSS_FEATURES = [f\'loss_{k}_{t}\' for k in LOSSES for t in (\'agree\', \'clash\')]\nFEATURE_NAMES = SPEC_FEATURES + CAND_FEATURES + LOSS_FEATURES\nN_FEATURES = len(FEATURE_NAMES)\n\n\ndef prep_spectrum(s):\n    """{mz, it, prec, adduct, mode} -> arrays used for matching (None when empty)."""\n    mz = np.asarray(s.get(\'mz\', ()), np.float64).ravel()\n    it = np.asarray(s.get(\'it\', ()), np.float64).ravel()\n    n = min(len(mz), len(it))\n    mz, it = mz[:n], it[:n]\n    ok = np.isfinite(mz) & np.isfinite(it) & (it > 0)\n    prec = float(s.get(\'prec\') or 0.0)\n    if prec > 0:\n        ok &= mz <= prec + 2.0\n    mz, it = mz[ok], it[ok]\n    if len(mz) < 2:\n        return None\n    order = np.argsort(-it)\n    mz, it = mz[order][:150], it[order][:150]\n    car = np.asarray(frag._carriers(s.get(\'adduct\'), s.get(\'mode\')), np.float64)\n    shifts = np.array([c + dh * H for c in car for dh in H_SHIFTS])\n    dh_of = np.array([dh for c in car for dh in H_SHIFTS])\n    return dict(mz=mz, it=it, lin=it / it.sum(), sq=np.sqrt(it) / np.sqrt(it).sum(), prec=prec if prec > 0 else float(mz.max()),\n                shifts=shifts, dh=dh_of, adduct=str(s.get(\'adduct\') or \'\'))\n\n\ndef _match(levels, p, tol):\n    """Per peak: fewest cleavages explaining it (0/1/2, 9 = none), smallest |error| (Da) and its dh."""\n    npk = len(p[\'mz\'])\n    q = p[\'mz\'][None, :] - p[\'shifts\'][:, None]                        # [n_shift, n_peak] neutral masses\n    best_k = np.full(npk, 9, np.int8)\n    best_err = np.full(npk, np.inf)\n    best_dh = np.zeros(npk, np.int8)\n    for k, arr in enumerate(levels[:3]):\n        if arr is None or len(arr) == 0:\n            continue\n        idx = np.searchsorted(arr, q)\n        lo = np.clip(idx - 1, 0, len(arr) - 1)\n        hi = np.clip(idx, 0, len(arr) - 1)\n        err = np.minimum(np.abs(arr[lo] - q), np.abs(arr[hi] - q))   # [n_shift, n_peak]\n        jmin = err.argmin(axis=0)\n        e = err[jmin, np.arange(npk)]\n        hit = (e <= tol) & (best_k == 9)\n        best_k[hit] = k\n        best_err[hit] = e[hit]\n        best_dh[hit] = p[\'dh\'][jmin[hit]]\n    return best_k, best_err, best_dh\n\n\ndef _spec_features(levels, p):\n    out = {}\n    for tol, tag in ((TOLS[1], \'\'), (TOLS[0], \'_tight\')):\n        k, err, dh = _match(levels, p, tol)\n        e1, e2 = k <= 1, k <= 2\n        if tag == \'\':\n            out[\'expl_k1_lin\'] = float(p[\'lin\'] @ e1)\n            out[\'expl_k2_lin\'] = float(p[\'lin\'] @ e2)\n            out[\'expl_k1_sqrt\'] = float(p[\'sq\'] @ e1)\n            out[\'expl_k2_sqrt\'] = float(p[\'sq\'] @ e2)\n            out[\'top5_k2\'] = float(e2[:5].mean())\n            out[\'top10_k2\'] = float(e2[:10].mean())\n            out[\'top10_k1\'] = float(e1[:10].mean())\n            out[\'top3_k1\'] = float(e1[:3].mean())\n            out[\'npeaks_k2\'] = float(e2.mean())\n            hi = p[\'mz\'] >= 0.5 * p[\'prec\']\n            out[\'hi_mass_k2\'] = float(p[\'lin\'][hi] @ e2[hi] / max(p[\'lin\'][hi].sum(), 1e-9)) if hi.any() else 0.0\n            lo = ~hi\n            out[\'lo_mass_k2\'] = float(p[\'lin\'][lo] @ e2[lo] / max(p[\'lin\'][lo].sum(), 1e-9)) if lo.any() else 0.0\n            w = p[\'lin\'][e2]\n            out[\'h0_share\'] = float(w @ (np.abs(dh[e2]) <= 1) / max(w.sum(), 1e-9)) if e2.any() else 0.0\n            out[\'mass_err_mda\'] = float(1000 * (w @ err[e2]) / max(w.sum(), 1e-9)) if e2.any() else TOLS[1] * 1000\n            out[\'k2_only_share\'] = float(p[\'lin\'] @ (k == 2))\n        else:\n            out[\'expl_k2_lin_tight\'] = float(p[\'lin\'] @ e2)\n            out[\'expl_k2_sqrt_tight\'] = float(p[\'sq\'] @ e2)\n    return out\n\n\ndef _observed_losses(p, tol=0.006):\n    """{loss: intensity share of peaks at precursor - loss} for one spectrum (precursor m/z taken as given)."""\n    out = {}\n    for name, (m, _) in LOSSES.items():\n        target = p[\'prec\'] - m\n        hit = np.abs(p[\'mz\'] - target) <= tol\n        out[name] = float(p[\'lin\'][hit].sum())\n    return out\n\n\ndef _cand_facts(smi):\n    from rdkit import Chem\n    m = Chem.MolFromSmiles(smi)\n    if m is None:\n        return None\n    pats = _patterns()\n    groups = {k: int(m.HasSubstructMatch(pt)) if pt is not None else 0 for k, pt in pats.items()}\n    ri = m.GetRingInfo()\n    heavy = m.GetNumHeavyAtoms()\n    arom = sum(a.GetIsAromatic() for a in m.GetAtoms())\n    sym = [a.GetSymbol() for a in m.GetAtoms()]\n    return dict(groups=groups, heavy_atoms=heavy, n_rings=ri.NumRings(), frac_aromatic=arom / max(heavy, 1),\n                n_O=sym.count(\'O\'), n_N=sym.count(\'N\'))\n\n\ndef features_for_list(spectra, smiles_list, cache=None, cfg_breaks=2):\n    """Feature matrix for candidates of one molecule (rows of NaN for unparsable SMILES)."""\n    cache = {} if cache is None else cache\n    preps = [p for p in (prep_spectrum(s) for s in (spectra or [])) if p is not None]\n    obs = None\n    if preps:\n        ol = [_observed_losses(p) for p in preps]\n        obs = {k: float(np.mean([o[k] for o in ol])) for k in LOSSES}\n    X = np.full((len(smiles_list), N_FEATURES), np.nan)\n    c = frag.resolve_cfg(dict(max_breaks=cfg_breaks))\n    for i, smi in enumerate(smiles_list):\n        key = (\'lv\', smi)\n        if key not in cache:\n            cache[key] = frag._levels_cached(smi, c, None)\n        lv = cache[key]\n        fkey = (\'facts\', smi)\n        if fkey not in cache:\n            try:\n                cache[fkey] = _cand_facts(smi)\n            except Exception:\n                cache[fkey] = None\n        facts = cache[fkey]\n        if lv is None or facts is None:\n            continue\n        row = {}\n        if preps:\n            sf = [_spec_features(lv, p) for p in preps]\n            for name in SPEC_FEATURES:\n                row[name] = float(np.mean([d[name] for d in sf]))\n        else:\n            for name in SPEC_FEATURES:\n                row[name] = 0.0\n        row[\'log_n_k1\'] = float(np.log1p(len(lv[1]) if len(lv) > 1 else 0))\n        row[\'log_n_k2\'] = float(np.log1p(len(lv[2]) if len(lv) > 2 else 0))\n        for name in (\'heavy_atoms\', \'n_rings\', \'frac_aromatic\', \'n_O\', \'n_N\'):\n            row[name] = float(facts[name])\n        for name in LOSSES:\n            seen = obs[name] if obs else 0.0\n            has = facts[\'groups\'][name]\n            row[f\'loss_{name}_agree\'] = seen * has\n            row[f\'loss_{name}_clash\'] = seen * (1 - has)\n        X[i] = [row[n] for n in FEATURE_NAMES]\n    return X\n\n\ndef centre_within(X):\n    """Candidate-list-relative copy: each column minus its list mean (NaN-safe)."""\n    with np.errstate(all=\'ignore\'):\n        mu = np.nanmean(X, axis=0, keepdims=True)\n    return X - np.where(np.isfinite(mu), mu, 0.0)\n\n\ndef full_features(spectra, smiles_list, cache=None):\n    X = features_for_list(spectra, smiles_list, cache)\n    return np.hstack([X, centre_within(X)])\n\n\nFULL_FEATURE_NAMES = FEATURE_NAMES + [f\'{n}_c\' for n in FEATURE_NAMES]\n'
_RR8_OVERLAY = '"""Deploy the v8 isomer reranker on a finished submission, with RR3-style rails (romanrozen).\n\nFor every molecule whose best library match is below `lib_tau`:\n  * G = the candidates of its final list that share the leader\'s molecular formula (the isomers the model compares);\n  * training-set structures in G keep their slots (FREEZE: a model trained on library spectra must not demote the\n    structures that do have library spectra); the other members of G are re-ordered among their own slots by\n        fused = z(-log position) + alpha * z(model score)            (z over the movable members)\n  * everything outside G, and every list with a strong library match, stays as it is.\nCandidate sets never change. Returns the new frame and a report; any error leaves the input unchanged (caller\'s job).\n"""\nfrom __future__ import annotations\n\nimport math\nimport time\n\nimport numpy as np\nimport pandas as pd\n\n\ndef _z(v):\n    v = np.asarray(v, float)\n    sd = v.std()\n    return (v - v.mean()) / sd if sd > 1e-12 else np.zeros_like(v)\n\n\ndef load_spectra(test_path):\n    t = pd.read_parquet(test_path)\n    out = {}\n    for r in t.itertuples(index=False):\n        ce = getattr(r, \'collision_energy_ev\', None)\n        try:\n            ce = float(np.mean(ce)) if ce is not None and len(ce) else float(\'nan\')\n        except Exception:\n            ce = float(\'nan\')\n        out.setdefault(str(r.molecule_id), []).append(dict(\n            mz=np.asarray(r.ms2_mzs, float), it=np.asarray(r.ms2_normalized_intensities, float),\n            prec=float(r.precursor_mz), adduct=str(r.adduct),\n            mode=1 if str(getattr(r, \'ionization_mode\', \'positive\')).lower() == \'positive\' else -1, ce=ce))\n    return out\n\n\ndef model_features(rf, frag, spectra, smiles, cache, fcache):\n    X = rf.full_features(spectra, smiles, cache)\n    m1 = frag.score_molecule(spectra, smiles, cfg=None, cache=fcache)\n    m2 = frag.score_molecule(spectra, smiles, cfg=frag.BASELINE_CFG, cache=fcache)\n    M = np.array([[np.nan if a is None else a, np.nan if b is None else b] for a, b in zip(m1, m2)], float)\n    with np.errstate(all=\'ignore\'):\n        Mc = M - np.nanmean(M, axis=0, keepdims=True)\n    return np.hstack([X, M, Mc])\n\n\ndef rerank_list(smiles, scores, frozen, alpha):\n    """smiles: the full list; scores/frozen: dicts for members of G (same formula as the leader). Returns new list."""\n    pos = {s: i for i, s in enumerate(smiles)}\n    movable = [s for s in scores if not frozen.get(s, False)]\n    if len(movable) < 2:\n        return list(smiles)\n    slots = sorted(pos[s] for s in movable)\n    base = _z([-math.log(pos[s] + 1) for s in movable])\n    rr = _z([scores[s] for s in movable])\n    fused = base + float(alpha) * rr\n    order = [movable[i] for i in np.argsort(-fused, kind=\'stable\')]\n    out = list(smiles)\n    for slot, s in zip(slots, order):\n        out[slot] = s\n    return out\n\n\ndef run(sub, lib_max, spectra, train_keys, booster, rf, frag, alpha=1.0, lib_tau=0.9, max_seconds=1500, log=print):\n    """sub: DataFrame molecule_id, smiles (\';\'-joined). Returns (new DataFrame, report)."""\n    from rdkit import Chem, RDLogger\n    from rdkit.Chem.rdMolDescriptors import CalcMolFormula\n    RDLogger.DisableLog(\'rdApp.*\')\n    t0 = time.monotonic()\n    info = {}\n\n    def facts(s):\n        if s not in info:\n            m = Chem.MolFromSmiles(s)\n            if m is None:\n                info[s] = (None, None)\n            else:\n                try:\n                    k = Chem.MolToInchiKey(m)[:14]\n                except Exception:\n                    k = None\n                info[s] = (CalcMolFormula(m), k)\n        return info[s]\n\n    rep = dict(molecules=len(sub), reranked=0, changed=0, top1_changed=0, skipped_library=0, skipped_group=0,\n               skipped_frozen=0, no_spectra=0, failed=0, timed_out=0, alpha=float(alpha), lib_tau=float(lib_tau))\n    cache, fcache, rows = {}, {}, []\n    for mid, joined in zip(sub.molecule_id.astype(str), sub.smiles.astype(str)):\n        smis = [s for s in joined.split(\';\') if s]\n        new = smis\n        if float(lib_max.get(mid, 0.0)) >= lib_tau:\n            rep[\'skipped_library\'] += 1\n        elif mid not in spectra:\n            rep[\'no_spectra\'] += 1\n        elif time.monotonic() - t0 > max_seconds:\n            rep[\'timed_out\'] += 1\n        elif len(smis) >= 2:\n            try:\n                f0 = facts(smis[0])[0]\n                group = [s for s in smis if f0 is not None and facts(s)[0] == f0]\n                frozen = {s: (facts(s)[1] in train_keys) for s in group}\n                if len(group) < 2:\n                    rep[\'skipped_group\'] += 1\n                elif sum(not v for v in frozen.values()) < 2:\n                    rep[\'skipped_frozen\'] += 1\n                else:\n                    F = model_features(rf, frag, spectra[mid], group, cache, fcache)\n                    sc = booster.predict(F)\n                    scores = {s: float(v) for s, v in zip(group, sc)}\n                    new = rerank_list(smis, scores, frozen, alpha)\n                    rep[\'reranked\'] += 1\n            except Exception as exc:\n                rep[\'failed\'] += 1\n                if rep[\'failed\'] <= 3:\n                    log(f\'[rr8] {mid}: {type(exc).__name__}: {exc}\')\n                new = smis\n        if new != smis:\n            rep[\'changed\'] += 1\n            rep[\'top1_changed\'] += int(new[0] != smis[0])\n        rows.append((mid, \';\'.join(new) if new else joined))\n        if len(cache) > 30000:\n            cache.clear()\n        if len(fcache) > 30000:\n            fcache.clear()\n    rep[\'seconds\'] = round(time.monotonic() - t0, 1)\n    return pd.DataFrame(rows, columns=[\'molecule_id\', \'smiles\']), rep\n'
_RR8_MODEL_Z = ''
assert hashlib.sha256(_RR8_FEATURES.encode()).hexdigest() == 'aec9012e72324095308af81c1408aa36f6a44cb00f6d4389e87529a68329d176'
assert hashlib.sha256(_RR8_OVERLAY.encode()).hexdigest() == 'e83b7986c46d0ef02bc6cfde17e891c9e7ee66a0eed8c716f5e3474e5663ccf7'


def _v8_lists(path):
    f = pd.read_csv(path, dtype=str, keep_default_na=False)
    return f, [s.split(';') for s in f.smiles.astype(str)]


def _v8_check(before, after):
    return (after.molecule_id.astype(str).tolist() == before.molecule_id.astype(str).tolist() == SAMPLE_IDS
            and all(set(x) == set(y) and len(x) == len(y) == len(set(y)) and all(y)
                    for x, y in zip(before.smiles.str.split(';'), after.smiles.str.split(';'))))


def _v8_write(frame):
    frame.to_csv(ROOT / 'submission.tmp.csv', index=False)
    os.replace(ROOT / 'submission.tmp.csv', ROOT / 'submission.csv')


try:
    _v8_ev = pd.read_parquet(ROOT / 'frozen_candidate_evidence.parquet', columns=['molecule_id', 'library_max'])
    V8_LIB = {str(m): float(v) for m, v in _v8_ev.groupby('molecule_id').library_max.max().items()}
except Exception:
    V8_LIB = {}

# 1) mass rank-1 rule
MASS_LEAD_REPORT = dict(status='off in this preset')
try:
    if MASS_ON and MASS_PPM:
        shutil.copyfile(ROOT / 'submission.csv', ROOT / 'submission_before_mass_lead.csv')
        _f, _lists = _v8_lists(ROOT / 'submission.csv')
        _rows, _moves = [], 0
        for _mid, _l in zip(_f.molecule_id.astype(str), _lists):
            ppm = MASS_PPM.get(_mid, {})
            if (len(_l) >= 2 and V8_LIB.get(_mid, 0.0) < MASS_LIB_TAU and _l[0] in ppm
                    and abs(ppm[_l[0]] - MASS_CENTER) > MASS_LEAD_OFF):
                for _s in _l[1:3]:
                    if _s in ppm and abs(ppm[_s] - MASS_CENTER) <= MASS_FREE:
                        _l = [_s] + [x for x in _l if x != _s]
                        _moves += 1
                        break
            _rows.append((_mid, ';'.join(_l)))
        _new = pd.DataFrame(_rows, columns=['molecule_id', 'smiles'])
        if _v8_check(_f, _new):
            _v8_write(_new)
            MASS_LEAD_REPORT = dict(status='ran', leader_moves=_moves)
        else:
            MASS_LEAD_REPORT = dict(status='check failed: answer kept')
    elif MASS_ON:
        MASS_LEAD_REPORT = dict(status='off: no mass table')
except Exception as exc:
    traceback.print_exc()
    MASS_LEAD_REPORT = dict(status='off after an error', exception=repr(exc)[:300])
    if (ROOT / 'submission_before_mass_lead.csv').is_file():
        shutil.copyfile(ROOT / 'submission_before_mass_lead.csv', ROOT / 'submission.csv')

# 2) learned isomer reranker
RR8_REPORT = dict(status='off in this preset')
_rr8_before = ROOT / 'submission_before_rr8.csv'
try:
    shutil.copyfile(ROOT / 'submission.csv', _rr8_before)
    _rr8_left = RR8_LIMIT_SECONDS - (time.time() - NB_T0)
    if not RR8:
        pass
    elif not globals().get('PIPELINE_DONE'):
        RR8_REPORT = dict(status='off: no pipeline answer in this run')
    elif _rr8_left < RR8_MIN_SECONDS:
        RR8_REPORT = dict(status='skipped: session time', seconds_left=round(_rr8_left))
    else:
        (CODE / 'rr_features.py').write_text(_RR8_FEATURES)
        (CODE / 'rr_overlay.py').write_text(_RR8_OVERLAY)
        for _p in (str(CODE), str(ROOT)):
            if _p not in sys.path:
                sys.path.insert(0, _p)
        for _m in ('rr_features', 'rr_overlay'):
            sys.modules.pop(_m, None)
        import frag_rescore as _rr8_frag
        import rr_features as _rr8_rf
        import rr_overlay as _rr8_ov
        import lightgbm as _rr8_lgb
        _rr8_txt = zlib.decompress(base64.b64decode(_RR8_MODEL_Z)).decode()
        assert hashlib.sha256(_rr8_txt.encode()).hexdigest() == '3b80e1c9adf90721c99bb4e817a05379dd8b26e0988a001bd112330a66d9122b', 'model text differs'
        _rr8_booster = _rr8_lgb.Booster(model_str=_rr8_txt)
        _rr8_frag.warmup()
        _rr8_sub, _ = _v8_lists(ROOT / 'submission.csv')
        _rr8_spec = _rr8_ov.load_spectra(COMP / 'test.parquet')
        _rr8_train = set(pd.read_parquet(COMP / 'train.parquet', columns=['inchikey14']).inchikey14.astype(str))
        _rr8_new, _rr8_rep = _rr8_ov.run(_rr8_sub, V8_LIB, _rr8_spec, _rr8_train, _rr8_booster, _rr8_rf, _rr8_frag,
                                         alpha=RR8_ALPHA, lib_tau=RR8_LIB_TAU,
                                         max_seconds=float(min(RR8_BUDGET_SECONDS, _rr8_left)))
        if _v8_check(_rr8_sub, _rr8_new):
            _v8_write(_rr8_new)
            RR8_REPORT = dict(status='ran', **_rr8_rep)
        else:
            RR8_REPORT = dict(status='check failed: answer kept', **_rr8_rep)
except Exception as exc:
    traceback.print_exc()
    RR8_REPORT = dict(status='off after an error', exception=repr(exc)[:400])
    try:
        if _rr8_before.is_file():
            shutil.copyfile(_rr8_before, ROOT / 'submission.csv')
    except Exception:
        traceback.print_exc()
try:
    (ROOT / 'v8_report.json').write_text(json.dumps(dict(mass=MASS_REPORT, mass_lead=MASS_LEAD_REPORT, rr=RR8_REPORT),
                                                    indent=2, default=str))
except Exception:
    traceback.print_exc()
final = pd.read_csv(ROOT / 'submission.csv', dtype=str, keep_default_na=False)
assert list(final.columns) == ['molecule_id', 'smiles']
assert final.molecule_id.tolist() == SAMPLE_IDS and final.molecule_id.is_unique
assert final.smiles.str.split(';').map(len).between(1, 25).all()
assert final.smiles.str.split(';').map(lambda a: all(bool(s) for s in a) and len(set(a)) == len(a)).all()
print('SUBMISSION READY:', ROOT / 'submission.csv', 'molecules', len(final), '| V8', V8, '| mass lead',
      json.dumps(MASS_LEAD_REPORT), '| RR', json.dumps(RR8_REPORT, default=str))